import unittest

from src.app import execute
from src import repository


class TaskTests(unittest.TestCase):
    def setUp(self):
        repository.TASKS.clear()

    def test_add_and_list_preserve_order(self):
        first = execute("add", title="first")
        second = execute("add", title="second")
        self.assertEqual(execute("list"), [first, second])
        self.assertFalse(first["completed"])

    def test_empty_list(self):
        self.assertEqual(execute("list"), [])

    def test_invalid_titles(self):
        for title in ("", "  ", None, "x" * 81):
            with self.subTest(title=title), self.assertRaises(ValueError):
                execute("add", title=title)

    def test_list_returns_copies(self):
        execute("add", title="first")
        execute("list")[0]["title"] = "changed"
        self.assertEqual(execute("list")[0]["title"], "first")


if __name__ == "__main__":
    unittest.main()

